using System;
using System.Collections.Generic;
using UnityEngine;

namespace ResolverMaster.Games.Plumber.View
{
    /// <summary>
    /// Pipe art generated by code in the cartoon style of the game: rounded pipes drawn with signed distance fields, a thick black
    /// outline (stays black whatever the tint), a soft round shading inside (white in the middle, tinted grey = empty, water color = full)
    /// and a separate untinted <see cref="Shine"/> overlay (light reflection along the side facing up-left).
    /// Source and sink cells get only a pipe stub from the centre to their opening: the fountain drawing sits on top and never rotates.
    /// Base orientation = rotation 0 of <see cref="PieceShapes"/> (texture y up = cell Up). Generated once per set of
    /// <see cref="PlumberConfig"/> shape values and kept for the whole run.
    /// </summary>
    public sealed class PipeSprites
    {
        const float Ink = 0.09f;
        const float EdgeShade = 0.74f;
        static readonly Vector2 LightDir = new Vector2(-0.6f, 0.8f);

        static readonly Dictionary<string, PipeSprites> s_cache = new Dictionary<string, PipeSprites>();

        readonly Dictionary<PieceKind, Sprite> _pieces = new Dictionary<PieceKind, Sprite>();
        readonly Dictionary<PieceKind, Sprite> _shine = new Dictionary<PieceKind, Sprite>();
        public Sprite Tile { get; private set; }
        public Sprite Disk { get; private set; }
        /// <summary>A water drop with the black outline (splashes).</summary>
        public Sprite Drop { get; private set; }

        public Sprite Get(PieceKind kind) => _pieces.TryGetValue(kind, out var s) ? s : null;

        /// <summary>The reflection overlay of a piece (null for empty cells).</summary>
        public Sprite Shine(PieceKind kind) => _shine.TryGetValue(kind, out var s) ? s : null;

        public static PipeSprites For(PlumberConfig cfg)
        {
            string key = string.Join("|", cfg.spriteSize, cfg.pipeWidth, cfg.pipeOutline, cfg.pipeShine, cfg.tileMargin, cfg.tileRadius);
            if (s_cache.TryGetValue(key, out var cached) && cached.IsAlive) return cached;
            var sprites = new PipeSprites();
            sprites.Generate(cfg);
            s_cache[key] = sprites;
            return sprites;
        }

        /// <summary>False after the textures were destroyed (e.g. editor domain/scene changes): regenerate.</summary>
        bool IsAlive => Tile != null && Disk != null && Drop != null && _pieces.Count > 0 && AllAlive();

        bool AllAlive()
        {
            foreach (var s in _pieces.Values)
                if (s == null) return false;
            foreach (var s in _shine.Values)
                if (s == null) return false;
            return true;
        }

        void Generate(PlumberConfig cfg)
        {
            int size = Mathf.Clamp(cfg.spriteSize, 32, 1024);
            float w = cfg.pipeWidth / 2f;
            var c = new Vector2(0.5f, 0.5f);
            const float beyond = 0.05f;   // pipe ends run past the edge, so they are cut flat exactly at the cell border
            var up = new Vector2(0.5f, 1 + beyond);
            var down = new Vector2(0.5f, -beyond);
            var right = new Vector2(1 + beyond, 0.5f);
            var left = new Vector2(-beyond, 0.5f);

            float Straight(Vector2 p) => Mathf.Min(Seg(p, c, up), Seg(p, c, down)) - w;
            var shapes = new Dictionary<PieceKind, Func<Vector2, float>>
            {
                [PieceKind.Straight] = Straight,
                [PieceKind.Curve] = p => Mathf.Abs((p - Vector2.one).magnitude - 0.5f) - w,
                [PieceKind.Tee] = p => Mathf.Min(Straight(p), Seg(p, c, right) - w),
                [PieceKind.Cross] = p => Mathf.Min(Straight(p), Mathf.Min(Seg(p, c, right), Seg(p, c, left)) - w),
                // source and sink: only the stub from the centre to the opening (the drawing covers the centre)
                [PieceKind.Source] = p => Seg(p, c, up) - w,
                [PieceKind.Sink] = p => Seg(p, c, up) - w,
            };
            foreach (var kv in shapes)
            {
                string n = "pipe_" + kv.Key.ToString().ToLowerInvariant();
                _pieces[kv.Key] = MakePipe(n, size, kv.Value, w, cfg.pipeOutline);
                _shine[kv.Key] = MakeShine(n + "_shine", size, kv.Value, w, cfg.pipeOutline, cfg.pipeShine);
            }

            float m = cfg.tileMargin, r = cfg.tileRadius;
            Tile = Make("pipe_tile", size, p =>
            {
                float half = 0.5f - m;
                float qx = Mathf.Abs(p.x - 0.5f) - (half - r);
                float qy = Mathf.Abs(p.y - 0.5f) - (half - r);
                return new Vector2(Mathf.Max(qx, 0), Mathf.Max(qy, 0)).magnitude + Mathf.Min(Mathf.Max(qx, qy), 0) - r;
            }, (d, px) => Mathf.Lerp(0.9f, 1f, Mathf.Clamp01((-d - 0.035f) / px + 0.5f)));
            Disk = Make("pipe_disk", size, p => (p - c).magnitude - (0.5f - 1.5f / size), (d, px) => 1f);
            // a drop: round bottom, pointed top, black outline
            Drop = Make("pipe_drop", size / 2, p =>
            {
                var q = p - new Vector2(0.5f, 0.4f);
                float circle = q.magnitude - 0.3f;
                float cone = Mathf.Max(Mathf.Abs(q.x) * 1.15f + (q.y - 0.5f) * 0.55f, -q.y);
                return Mathf.Min(circle, cone);
            }, (d, px) => Mathf.Lerp(Ink, 1f, Mathf.Clamp01((-d - 0.08f) / px + 0.5f)));
        }

        /// <summary>Body: black outline, then a round shading (darker at the edges, white along the middle).</summary>
        static Sprite MakePipe(string name, int size, Func<Vector2, float> sdf, float halfWidth, float outline) =>
            Make(name, size, sdf, (d, px) =>
            {
                float depth = Mathf.Clamp01((-d - outline) / Mathf.Max(0.001f, halfWidth - outline));
                float body = Mathf.Lerp(EdgeShade, 1f, Mathf.Sqrt(depth));
                return Mathf.Lerp(Ink, body, Mathf.Clamp01((-d - outline) / px + 0.5f));
            });

        /// <summary>White reflection band on the side whose outward normal faces <see cref="LightDir"/>.</summary>
        static Sprite MakeShine(string name, int size, Func<Vector2, float> sdf, float halfWidth, float outline, float strength)
        {
            var tex = NewTexture(name, size);
            var px = new Color32[size * size];
            float pixel = 1f / size, e = pixel;
            var light = LightDir.normalized;
            float inner = outline + (halfWidth - outline) * 0.18f, outer = outline + (halfWidth - outline) * 0.48f;
            for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                var p = new Vector2((x + 0.5f) * pixel, (y + 0.5f) * pixel);
                float d = sdf(p);
                float a = 0f;
                if (d < 0)
                {
                    var grad = new Vector2(sdf(p + new Vector2(e, 0)) - sdf(p - new Vector2(e, 0)), sdf(p + new Vector2(0, e)) - sdf(p - new Vector2(0, e)));
                    float facing = grad.sqrMagnitude > 0 ? Vector2.Dot(grad.normalized, light) : 0f;
                    float band = Mathf.Clamp01((-d - inner) / pixel + 0.5f) * Mathf.Clamp01((outer + d) / pixel + 0.5f);
                    a = band * Mathf.Clamp01((facing - 0.25f) / 0.25f) * strength;
                }
                px[y * size + x] = new Color32(255, 255, 255, (byte)Mathf.RoundToInt(a * 255));
            }
            return Finish(tex, px, name);
        }

        static float Seg(Vector2 p, Vector2 a, Vector2 b)
        {
            var pa = p - a;
            var ba = b - a;
            float h = Mathf.Clamp01(Vector2.Dot(pa, ba) / Vector2.Dot(ba, ba));
            return (pa - ba * h).magnitude;
        }

        /// <summary>Rasterizes a signed distance (cell fractions, negative inside) with an anti-aliased edge; <paramref name="shade"/> gives
        /// the grey level from the distance and the pixel size.</summary>
        static Sprite Make(string name, int size, Func<Vector2, float> sdf, Func<float, float, float> shade)
        {
            var tex = NewTexture(name, size);
            var px = new Color32[size * size];
            float pixel = 1f / size;
            for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                var p = new Vector2((x + 0.5f) * pixel, (y + 0.5f) * pixel);
                float d = sdf(p);
                float alpha = Mathf.Clamp01(0.5f - d / pixel);
                if (alpha <= 0f)
                {
                    px[y * size + x] = new Color32(255, 255, 255, 0);
                    continue;
                }
                byte g = (byte)Mathf.RoundToInt(Mathf.Clamp01(shade(d, pixel)) * 255);
                px[y * size + x] = new Color32(g, g, g, (byte)Mathf.RoundToInt(alpha * 255));
            }
            return Finish(tex, px, name);
        }

        static Texture2D NewTexture(string name, int size) => new Texture2D(size, size, TextureFormat.RGBA32, false)
        {
            name = name,
            wrapMode = TextureWrapMode.Clamp,
            filterMode = FilterMode.Bilinear,
            hideFlags = HideFlags.HideAndDontSave,
        };

        static Sprite Finish(Texture2D tex, Color32[] px, string name)
        {
            tex.SetPixels32(px);
            tex.Apply(false, true);
            int size = tex.width;
            var sprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
            sprite.name = name;
            sprite.hideFlags = HideFlags.HideAndDontSave;
            return sprite;
        }
    }
}
